static void joint_frame(){if(!joint_trace())return;const char* path=std::getenv("GPU_PR10_API_TRACE"),*ui=std::getenv("GPU_PR10_UI_TRACE");if(!path||!ui)return;static unsigned last=0;unsigned request=0;std::string p=std::string(ui)+".request";FILE* rf=std::fopen(p.c_str(),"r");if(!rf)return;int n=std::fscanf(rf,"%u",&request);std::fclose(rf);if(n!=1||last==request)return;last=request;if(FILE* f=std::fopen(path,"a")){std::fprintf(f,"{\"api\":\"actual_joint_frame\",\"request\":%u,\"created\":%u,\"destroyed\":%u,\"joints\":[",request,joint_created,joint_destroyed);bool first=true;for(auto r:joint_refs){if(!joint_valid(r))continue;if(!first)std::fputc(',',f);first=false;joint_json(f,r);}std::fputs("]}\n",f);std::fclose(f);}joint_refs.erase(std::remove_if(joint_refs.begin(),joint_refs.end(),[](auto r){return !joint_valid(r);}),joint_refs.end());}
